}

occ() {
  runuser --user www-data -- php /var/www/html/occ "$@"
}

occ() {
  php /var/www/html/occ "$@"
}

arguments.command:
python3 - <<'PY'
for module in ('websocket','websockets'):
 try:
  m=__import__(module); print(module, getattr(m,'__version__','installed'))
 except Exception as e: print(module, 'missing')
PY
curl -skI https://10.77.20.101/api/current | head -5; curl -skI https://10.77.20.101/api/current/ | head -5

set -a; . ./.env; set +a; NODE_TLS_REJECT_UNAUTHORIZED=0 node <<'JS'
const password=process.env.TRUENAS_PASSWORD;
async function test(username) {
  return await new Promise((resolve) => {
    const ws=new WebSocket('wss://10.77.20.101/api/current');
    const timer=setTimeout(()=>{ws.close(); resolve('timeout')},5000);
